/* Literal native Finder oracle: review-fix-desktop-evidence/mac-long-names.png
 * (Mac OS 8.1, as Icons checked in mac-view-menu.png). All these names remain
 * complete on one line. Geometry is independently graded by disjoint extents,
 * not by a screenshot generated by our renderer. */
#include <stdio.h>
#include <string.h>
#include "finder_desktop.h"
#include "finder_windows.h"
#include "geneva9.h"
#include "test_assert.h"
TEST_HARNESS();
static const char *const names[] = {
    "123.EXE", "123.MNU", "CALC.EXE", "CALCULAT.EXE", "CPANELS.EXE",
    "INITBASE.EXE", "INITBASE.OVL", "LEDGER.TXT", "MICHAEL.CFG",
    "NOTEPAD.EXE", "PAINT.EXE", "SCRAPBK.EXE", "TEXT.EXE", "WORD.EXE",
    "A Long Name for Testing.txt", "WWWWWWWWWWWWWWWWWWWWWWWWWWW.TXT"
};
static int width_of(const char *s)
{
    int width=0;
    for (;*s;s++) width+=geneva9_advance[(unsigned char)*s-32];
    return width;
}
static void full_names(void)
{
    finder_desk_t fd;
    finder_desk_icon_t icon;
    char shown[64];
    for (unsigned i=0;i<sizeof names/sizeof names[0];i++) {
        finder_desk_init(&fd,&icon,1,(rgn_rect_t){20,0,480,640});
        finder_desk_add(&fd,FINDER_ICON_FILE,names[i],240,30,1);
        finder_desk_label_name(&fd,0,shown);
        CHECK(strcmp(shown,names[i])==0,"native icon view retains the complete literal name");
        rgn_rect_t r=finder_desk_label_rect(&fd,0);
        CHECK(r.right-r.left==width_of(names[i])+6,"full single-line label has room for every glyph");
        CHECK(r.top==64 && r.bottom==77,"full name occupies one line below its icon");
    }
}
static void layout_properties(void)
{
    finder_desk_t fd;
    finder_desk_icon_t icons[16];
    static unsigned char pixels[1024*1024];
    bitmap_t bm={0};
    bm.base=pixels;bm.width=1024;bm.height=1024;bm.pitch=1024;
    bm.bpp=8;bm.bytes_per_pixel=1;
    for(int width=128;width<=640;width+=17) {
        finder_desk_init(&fd,icons,16,(rgn_rect_t){20,0,1024,(int16_t)width});
        for(int i=0;i<16;i++) finder_desk_add(&fd,FINDER_ICON_FILE,names[i],0,0,1);
        finder_win_layout_icons(&fd,fd.bounds);
        int disjoint=1,full=1,painted=1;
        for(int i=0;i<16;i++) {
            rgn_rect_t a=finder_desk_label_rect(&fd,i);
            full &= a.right-a.left==width_of(names[i])+6 &&
                a.left>=0 && a.bottom-a.top==13;
            for(int j=0;j<i;j++)
                disjoint &= !finder_rect_intersects(a,finder_desk_label_rect(&fd,j));
            finder_desk_t one=fd;one.icons=&icons[i];one.n=1;
            for(int selected=0;selected<2;selected++) {
                icons[i].selected=(uint8_t)selected;
                memset(pixels,0x7e,sizeof pixels);
                finder_desk_paint(&one,&bm,NULL);
                for(int y=a.top;y<a.bottom;y++) for(int x=0;x<1024;x++)
                    if(pixels[y*1024+x]!=0x7e && (x<a.left || x>=a.right)) painted=0;
                /* The last glyph must really be painted at its full-name
                 * position, not merely granted a wide empty hit rectangle. */
                int start=a.left+3+width_of(names[i])-width_of(names[i]+strlen(names[i])-1);
                int tail_ink=0;
                unsigned char ink=selected?1:0;
                for(int y=a.top+1;y<a.top+12;y++)
                    for(int x=start;x<a.right-3;x++) tail_ink+=pixels[y*1024+x]==ink;
                painted &= tail_ink>0;
            }
        }
        CHECK(full,"full icon bands retain every literal glyph and one-line height");
        CHECK(disjoint,"automatic full-name labels never overlap");
        CHECK(painted,"selection and complete label ink stay inside the full-name band");
        CHECK(finder_win_layout_icons(&fd,fd.bounds)==0,"automatic arrangement is idempotent");
        for(int scroll=0;scroll<200;scroll+=17) {
            for(int i=0;i<16;i++) icons[i].x-=17;
            disjoint=1;
            for(int i=0;i<16;i++) for(int j=0;j<i;j++)
                disjoint &= !finder_rect_intersects(finder_desk_label_rect(&fd,i),
                                                   finder_desk_label_rect(&fd,j));
            CHECK(disjoint,"viewport scrolling never pins labels onto their neighbors");
        }
    }
}

static void list_names(void)
{
    char shown[FINDER_ICON_NAME_MAX+3];
    int fits=1,unchanged=1,middle=1;
    for(int width=0;width<=300;width++) for(int i=0;i<16;i++) {
        finder_win_list_name(names[i],width,shown);
        fits &= width_of(shown)<=width;
        if(width_of(names[i])<=width) unchanged &= strcmp(shown,names[i])==0;
        else if(width<12) middle &= !shown[0];
        else {
            const char *ellipsis=strstr(shown,"...");
            if(!ellipsis) {middle=0;continue;}
            size_t prefix=(size_t)(ellipsis-shown),suffix=strlen(ellipsis+3);
            middle &= prefix+suffix<strlen(names[i]) &&
                !strncmp(shown,names[i],prefix) &&
                !strcmp(ellipsis+3,names[i]+strlen(names[i])-suffix);
            if(width>=30) middle &= prefix>0 && suffix>0;
        }
    }
    CHECK(fits,"list-column spelling fits the allocated width");
    CHECK(unchanged,"list names that fit stay complete");
    CHECK(middle,"only list overflow omits the middle and preserves both ends");
}
int main(void)
{
    full_names();
    layout_properties();
    list_names();
    return TEST_SUMMARY("test_finder_labels");
}
